<div class="row g-3 mb-3"><?php foreach(array('Hari ini'=>'harian','7 hari'=>'mingguan','30 hari'=>'bulanan') as $l=>$k): ?><div class="col-4"><div class="small-box text-bg-success"><div class="inner"><h3><?= (int)$periode[$k] ?></h3><p>Kunjungan <?= $l ?></p></div></div></div><?php endforeach; ?></div>
<div class="card mb-3"><div class="card-header">Kunjungan &amp; klik WhatsApp 60 hari</div><div class="card-body"><canvas id="ch" height="90"></canvas></div></div>
